import sys
sys.path.insert(0,'/downloads/fiqh-alruh-source/gen')
import lib
head,W,R,S=lib.load()
K='https://quran.ksu.edu.sa/tafseer/saadi/sura%s-aya%s.html'
def it(i,t,d,ref,kind='تفسير السعدي'): return {'id':i,'t':t,'d':d,'kind':kind,'ref':ref}
def setg(L,g,i,new):
    L['meaning'][g]=[new if x['id']==i else x for x in L['meaning'][g]]
for C in W:
  for L in C['lessons']:
    if L['id']=='siyam1':
      L['meaning']['why'].append(it('m7','كيف يقود الصيام إلى التقوى','قال السعدي في تفسير ﴿لعلكم تتقون﴾: إن الصيام من أكبر أسباب التقوى، لأن فيه امتثال أمر الله واجتناب نهيه. وذكر من وجوه ذلك: أن الصائم يترك ما حرم الله عليه من الأكل والشرب والجماع ونحوها مما تميل إليه نفسه، متقرباً بذلك إلى الله راجياً ثوابه. وأنه يدرب نفسه على مراقبة الله فيترك ما تهوى مع قدرته عليه لعلمه باطلاع الله عليه. وأنه يضيق مجاري الشيطان فيضعف نفوذه وتقل المعاصي. وأن الغني إذا ذاق ألم الجوع حمله ذلك على مواساة الفقراء.',K%(2,183)))
      L['meaning']['why'].append(it('m8','شهر القرآن وتكميل العدة','قال السعدي في تفسير آية ﴿شهر رمضان الذي أنزل فيه القرآن﴾: هذا الشهر حصل فيه الفضل العظيم وهو القرآن المشتمل على الهداية لمصالح الدين والدنيا والفرقان بين الحق والباطل، فحقيق بشهر هذا فضله أن يكون موسماً مفروضاً فيه الصيام. وفي ﴿ولتكملوا العدة﴾ قال: لئلا يتوهم أن المقصود من صيام رمضان يحصل ببعضه، وفيه شكر الله عند الإتمام والتكبير عند انقضائه.',K%(2,185)))
      setg(L,'impact','m5',it('m5','اليسر','قال تعالى: يريد الله بكم اليسر ولا يريد بكم العسر. وقال السعدي في تفسيرها: يريد الله أن ييسر الطرق الموصلة إلى رضوانه أعظم تيسير، وجميع ما أمر الله به في أصله في غاية السهولة، وإذا عرضت عوارض توجب ثقله سهله بإسقاطه أو تخفيفه، ويدخل في ذلك جميع الرخص. فرخصة المريض والمسافر داخلة في هذا اليسر.',K%(2,185)))
    if L['id']=='zakah1':
      setg(L,'why','m1',it('m1','طهرة وتزكية','قال تعالى: خذ من أموالهم صدقة تطهرهم وتزكيهم بها. وقال السعدي: الصدقة هنا الزكاة المفروضة، ومعنى ﴿تطهرهم﴾ تطهرهم من الذنوب والأخلاق الرذيلة، ومعنى ﴿وتزكيهم﴾ تنميهم وتزيد في أخلاقهم الحسنة وأعمالهم الصالحة وثوابهم، وتنمي أموالهم.',K%(9,103)))
      setg(L,'symbols','m3',it('m3','الحبة وسبع سنابل','ضرب الله مثلاً للإنفاق في سبيله بحبة تنبت سبع سنابل في كل سنبلة مائة حبة. وقال السعدي: هذا إحضار لصورة المضاعفة بمثل يشاهده العبد ببصره فيشاهدها ببصيرته، فتنقاد النفس للإنفاق وتؤمل المضاعفة. والمضاعفة عنده بحسب حال المنفق وإخلاصه وصدقه، وحال النفقة وحلها ونفعها ووقوعها موقعها. والمثل في الآية عن الإنفاق في سبيل الله عموماً وليس خاصاً بالزكاة المفروضة.',K%(2,261)))
      setg(L,'symbols','m4',it('m4','الطيب من المال','قال تعالى: يا أيها الذين آمنوا أنفقوا من طيبات ما كسبتم ولا تيمموا الخبيث منه تنفقون. وقال السعدي: فكما من الله بتسهيل تحصيل المال فأنفقوا منه شكراً لله وأداء لبعض حقوق إخوانكم وتطهيراً لأموالكم، واقصدوا الطيب الذي تحبونه لأنفسكم ولا تقصدوا الرديء الذي لا تأخذونه إلا على وجه الإغماض. ونفع الصدقات والأعمال عائد إلى المنفقين.',K%(2,267)))
    if L['id']=='hajj1':
      setg(L,'why','m1',it('m1','نداء إبراهيم','قال تعالى: وأذن في الناس بالحج يأتوك رجالاً وعلى كل ضامر يأتين من كل فج عميق. وقال السعدي: أي أعلمهم به وادعهم إليه وبلغ دانيهم وقاصيهم فرضه وفضيلته، فإذا دعوتهم أتوك حجاجاً وعماراً مشاة من الشوق وعلى كل ناقة ضامر من كل بلد بعيد. وذكر أن الخليل عليه السلام ثم محمداً ﷺ دعوا الناس إلى حج هذا البيت، وقد حصل ما وعد الله به.',K%(22,27)))
      setg(L,'impact','m5',it('m5','المقصود من الحج وزاده','قال تعالى: وتزودوا فإن خير الزاد التقوى. وقال السعدي في تفسير آية الحج: المقصود من الحج الذل والانكسار لله والتقرب إليه بما أمكن من القربات والتنزه عن مقارفة السيئات، وبذلك يكون الحج مبروراً. وفسر الرفث بالجماع ومقدماته الفعلية والقولية، والفسوق بجميع المعاصي ومنها محظورات الإحرام، والجدال بالمماراة والمنازعة.',K%(2,197)))
      setg(L,'impact','m6',it('m6','الشعائر آيات بينات','قال السعدي في تفسير ﴿فيه آيات بينات﴾: يحتمل أن جميع أجزاء الحج ومفرداته آيات بينات كالطواف والسعي والوقوف بعرفة ومزدلفة والرمي، والآية في ذلك ما جعله الله في القلوب من تعظيمها واحترامها وبذل نفائس النفوس والأموال في الوصول إليها وتحمل كل مشقة لأجلها. وقال إن في أفعالها من الحكم والمصالح ما يعجز الخلق عن إحصاء بعضه.',K%(3,97)))
lib.save(head,W,R,S)
